from collections import deque

def components(grid):
    R,C=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(R):
        for c in range(C):
            if grid[r][c] and (r,c) not in seen:
                q=[(r,c)];seen.add((r,c)); cells=[]
                while q:
                    y,x=q.pop();cells.append((y,x))
                    for dy in (-1,0,1):
                      for dx in (-1,0,1):
                        p=(y+dy,x+dx)
                        if (dy or dx) and 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]] and p not in seen:
                          seen.add(p);q.append(p)
                comps.append(cells)
    return sorted(comps,key=len,reverse=True)

def transform(grid):
    cs=components(grid)[:2]
    if len(cs)!=2: raise ValueError(len(cs))
    bbs=[]
    for cells in cs:
        r0=min(r for r,c in cells);r1=max(r for r,c in cells);c0=min(c for r,c in cells);c1=max(c for r,c in cells)
        bbs.append((r0,r1,c0,c1))
    # order left to right
    bbs.sort(key=lambda b:b[2])
    (ar0,ar1,ac0,ac1),(br0,br1,bc0,bc1)=bbs
    wa=ac1-ac0+1;wb=bc1-bc0+1
    if wa != wb: print('width mismatch',bbs)
    h=min(ar1-ar0+1,br1-br0+1);w=min(wa,wb)
    dif=[]
    for r in range(h):
        row=[]
        for c in range(w): row.append(8 if grid[ar0+r][ac0+c]!=grid[br0+r][bc0+c] else 0)
        dif.append(row)
    rows=[i for i,x in enumerate(dif) if any(x)]
    if not rows:return [[0]*w]
    return dif[min(rows):max(rows)+1]

